'use strict';
const SeenTalk=(()=>{
 const dialog=document.createElement('dialog');dialog.id='npc-dialog';dialog.setAttribute('aria-labelledby','npc-title');dialog.innerHTML='<button class="icon-close talk-close" type="button" aria-label="Close conversation">'+seenCloseIcon+'</button><span class="talk-role"></span><div class="talk-avatar" aria-hidden="true"><span></span></div><h2 id="npc-title"></h2><p class="talk-line" role="status"></p><div class="talk-options"></div>';document.body.append(dialog);let afterClose=null;
 function close(){if(dialog.open)dialog.close()}
 dialog.querySelector('.talk-close').onclick=close;dialog.addEventListener('close',()=>{const fn=afterClose;afterClose=null;fn?.();document.querySelector(document.body.dataset.scene==='screening'?'#room-world':document.body.dataset.scene==='arcade-room'?'#arcade-world':'#world').focus({preventScroll:true})});
 function show({name,role='CINEMA HOST',line,options=[],onClose}){afterClose=onClose||null;dialog.querySelector('.talk-role').textContent=role;dialog.querySelector('h2').textContent=name;dialog.querySelector('.talk-line').textContent=line;const actions=dialog.querySelector('.talk-options');actions.replaceChildren();for(const option of options){const button=document.createElement('button');button.type='button';button.textContent=option.label;button.onclick=option.action;actions.append(button)}if(!dialog.open)dialog.showModal();dialog.querySelector('.talk-close').focus({preventScroll:true})}
 function staff(person){const ticket=person.id==='lobby:npc:0',popcorn=person.id==='lobby:npc:1';if(ticket){show({name:'Mia',role:'TICKET BOOTH · NPC',line:'Welcome to SEEN. Which story shall we find you a seat for?',options:[...rooms.map(r=>({label:`SCREEN ${r.n} · ${r.name}`,action:()=>{close();near=r;enter()}})),{label:'Where is the arcade?',action:()=>{close();walkToGame()}}]})}else if(popcorn){show({name:'Leo',role:'POPCORN SHOP · NPC',line:'One film, one conversation, one popcorn. What can I get you?',options:[{label:'A popcorn, please',action:()=>show({name:'Leo',role:'POPCORN SHOP · NPC',line:'Yes! A fresh popcorn, on the house. Enjoy the screening.',options:[{label:'Thank you!',action:()=>{let snack=document.querySelector('#snack-receipt');if(!snack){snack=document.createElement('span');snack.id='snack-receipt';snack.textContent='POPCORN · ON THE HOUSE';document.querySelector('#lobby-scene').append(snack)}setTimeout(()=>snack.remove(),4500);close()}}]})},{label:'What do you recommend?',action:()=>show({name:'Leo',role:'POPCORN SHOP · NPC',line:'Try a screening first, then talk about the detail that stayed with you. The arcade is great for an encore.',options:[{label:'Sounds good',action:close}]})}]})}else show({name:person.npc?'A fellow film lover':person.name,role:person.npc?'CINEMA GUEST · NPC':'LIVE VISITOR',line:person.npc?'I came for a film and stayed for the conversation. Have you explored the screenings yet?':'Another visitor is exploring the cinema with you.',options:[{label:'See you around',action:close}]})}
 async function askSeat(person,{seatId,scene,onYes}){show({name:person.npc?'A fellow film lover':person.name,role:person.npc?'SEATED GUEST · NPC':'LIVE VISITOR',line:`This is seat ${seatId}. Would you like to ask if you can take this seat?`,options:[{label:'Ask to change seats',action:async()=>{show({name:person.npc?'A fellow film lover':person.name,role:person.npc?'SEATED GUEST · NPC':'LIVE VISITOR',line:'“Would you mind changing seats?”',options:[]});let answer;if(person.npc){await new Promise(r=>setTimeout(r,650));if(!dialog.open)return;answer=person.id.split(':').at(-1)!=='1'}else{answer=await SeenHub.requestSeat(person,{seatId,scene});if(!dialog.open)return}const line=answer===true?'Yes — you can have my seat. I’ll find another spot.':answer===false?'No, I’d like to stay in this seat. Thanks for asking.':'No reply yet. They may be reading or away. Try another seat.';show({name:person.npc?'A fellow film lover':person.name,role:person.npc?'SEATED GUEST · NPC':'LIVE VISITOR',line,options:[{label:answer===true?'Take the seat':'Choose another seat',action:()=>{close();if(answer===true)onYes()}}]})}},{label:'Never mind',action:close}]})}
 function incoming(req,onYes){let answered=false;const reply=yes=>{answered=true;SeenHub.replySeat(req,yes);close();if(yes)onYes()};show({name:req.name,role:'SEAT REQUEST · LIVE VISITOR',line:`Would you let ${req.name} take seat ${req.seatId}? If you say Yes, you’ll move to another available seat.`,options:[{label:'No · Keep my seat',action:()=>reply(false)},{label:'Yes · I can move',action:()=>reply(true)}],onClose:()=>{if(!answered)SeenHub.replySeat(req,false)}})}
 return{staff,askSeat,incoming,close};
})();
